operation.add:
if (
    isset($this->request->get['route']) &&
    $this->request->get['route'] === 'product/category' &&
    isset($setting['name']) &&
    $setting['name'] === 'Static Sidebar' &&
    isset($this->request->server['HTTP_USER_AGENT']) &&
    preg_match('/(Mobile|Android|iPhone|iPod)/i', $this->request->server['HTTP_USER_AGENT'])
) {
    $data['block_content'] = str_replace(
        'src="image/catalog/slider/420x816 a.png"',
        'data-src="image/catalog/slider/420x816 a.png"',
        $data['block_content']
    );
}
